namespace ghidra.app.context;




using docking;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.util;

public class ProgramSymbolActionContext : ProgramActionContext, ProgramLocationSupplierContext {

	private List<Symbol> symbols = new List<Symbol>();

	public ProgramSymbolActionContext(ComponentProvider provider, Program program,
			List<Symbol> symbols, Component sourceComponent) : base(provider, program, sourceComponent)
    {
		this.symbols = symbols == null ? Collections.emptyList() : symbols;
	}

	public int getSymbolCount() {
		return symbols.size();
	}

	public Symbol getFirstSymbol() {
		if (symbols.isEmpty()) {
			return null;
		}
		return symbols.get(0);
	}

	public Iterable<Symbol> getSymbols() {
		return symbols;
	}

	/* @Override */
	public ProgramLocation getLocation() {
		if (symbols.isEmpty()) {
			return null;
		}
		Symbol s = symbols.get(0);
		return s.getProgramLocation();
	}
}
